#include <vector>
#include <algorithm>

class Solution {
public:
    long long maxAlternatingSumWithDeletion(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return n == 1 ? nums[0] : 0;

        std::vector<long long> L_pos(n), L_neg(n);
        L_pos[0] = nums[0];
        L_neg[0] = -1e18;

        for (int i = 1; i < n; ++i) {
            L_pos[i] = std::max((long long)nums[i], L_neg[i - 1] + nums[i]);
            L_neg[i] = L_pos[i - 1] - nums[i];
        }

        std::vector<long long> R_pos(n), R_neg(n);
        R_pos[n - 1] = nums[n - 1];
        R_neg[n - 1] = -nums[n - 1];

        for (int i = n - 2; i >= 0; --i) {
            R_pos[i] = std::max((long long)nums[i], nums[i] + R_neg[i + 1]);
            R_neg[i] = std::max((long long)-nums[i], -nums[i] + R_pos[i + 1]);
        }

        long long ans = -1e18;
        for (int i = 0; i < n; ++i) {
            ans = std::max({ans, L_pos[i], L_neg[i]});
        }

        for (int i = 1; i < n - 1; ++i) {
            if (L_pos[i - 1] != -1e18) ans = std::max(ans, L_pos[i - 1] + R_neg[i + 1]);
            if (L_neg[i - 1] != -1e18) ans = std::max(ans, L_neg[i - 1] + R_pos[i + 1]);
        }

        for (int i = 1; i < n; ++i) ans = std::max(ans, R_pos[i]);
        for (int i = 0; i < n - 1; ++i) ans = std::max(ans, L_pos[i]);
        return ans;
    }
};

