            R_neg[i] = Math.max((long)-nums[i], -nums[i] + R_pos[i + 1]);
        }

        long ans = (long)-1e18;
        for (int i = 0; i < n; i++) {
            ans = Math.max(ans, Math.max(L_pos[i], L_neg[i]));
        }

        for (int i = 1; i < n - 1; i++) {
            if (L_pos[i - 1] != (long)-1e18) ans = Math.max(ans, L_pos[i - 1] + R_neg[i + 1]);
            if (L_neg[i - 1] != (long)-1e18) ans = Math.max(ans, L_neg[i - 1] + R_pos[i + 1]);
